static void test_ld2string(void) {
    char buf[32];
    long double v;
    int sz;

    v = 0.0 / 0.0;
    sz = ld2string(buf, sizeof(buf), v, LD_STR_AUTO);
    assert(sz == 3);
    assert(!strcmp(buf, "nan"));
}

static void test_fixedpoint_d2string(void) {
    char buf[32];
    d2stringDest dest;
    double v;
    int sz;
    dest.dst = buf;
    dest.dstlen = sizeof buf;
    v = 0.0;
    sz = fixedpoint_d2string(&dest, v, 4);
    assert(sz == 6);
    assert(!strcmp(buf, "0.0000"));
    sz = fixedpoint_d2string(&dest, v, 1);
    assert(sz == 3);
    assert(!strcmp(buf, "0.0"));
    v = 0.01;
    sz = fixedpoint_d2string(&dest, v, 4);
    assert(sz == 6);
    assert(!strcmp(buf, "0.0100"));
    sz = fixedpoint_d2string(&dest, v, 1);
    assert(sz == 3);
    assert(!strcmp(buf, "0.0"));
    v = -0.01;
    sz = fixedpoint_d2string(&dest, v, 4);
    assert(sz == 7);
    assert(!strcmp(buf, "-0.0100"));
     v = -0.1;
    sz = fixedpoint_d2string(&dest, v, 1);
    assert(sz == 4);
    assert(!strcmp(buf, "-0.1"));
    v = 0.1;
    sz = fixedpoint_d2string(&dest, v, 1);
    assert(sz == 3);
    assert(!strcmp(buf, "0.1"));
    v = 0.01;
    sz = fixedpoint_d2string(&dest, v, 17);
    assert(sz == 19);
    assert(!strcmp(buf, "0.01000000000000000"));
    v = 10.01;
    sz = fixedpoint_d2string(&dest, v, 4);
    assert(sz == 7);
    assert(!strcmp(buf, "10.0100"));
    /* negative tests */
    sz = fixedpoint_d2string(&dest, v, 18);
    assert(sz == 0);
    sz = fixedpoint_d2string(&dest, v, 0);
    assert(sz == 0);
    dest.dstlen = 1;
    sz = fixedpoint_d2string(&dest, v, 1);
    assert(sz == 0);
}

